package com.highpass.runspot.chat.outbox;import com.highpass.runspot.common.domain.BaseTimeEntity;import jakarta.persistence.*;import java.time.LocalDateTime;import lombok.AccessLevel;import lombok.Getter;import lombok.NoArgsConstructor;
@Getter @Entity @Table(name="chat_outbox",indexes=@Index(name="idx_chat_outbox_publish",columnList="status,next_attempt_at,id"))@NoArgsConstructor(access=AccessLevel.PROTECTED)public class ChatOutbox extends BaseTimeEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="aggregate_id",nullable=false)private Long aggregateId;@Column(nullable=false,length=200)private String destination;@Lob @Column(nullable=false,columnDefinition="TEXT")private String payload;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private OutboxStatus status;@Column(nullable=false)private int attempts;@Column(name="next_attempt_at",nullable=false)private LocalDateTime nextAttemptAt;@Column(name="published_at")private LocalDateTime publishedAt;public static ChatOutbox pending(Long aggregateId,String destination,String payload){ChatOutbox o=new ChatOutbox();o.aggregateId=aggregateId;o.destination=destination;o.payload=payload;o.status=OutboxStatus.PENDING;o.nextAttemptAt=LocalDateTime.now();return o;}public void published(){status=OutboxStatus.PUBLISHED;publishedAt=LocalDateTime.now();}public void failed(){attempts++;long delay=Math.min(300,1L<<Math.min(attempts,8));nextAttemptAt=LocalDateTime.now().plusSeconds(delay);}}
